    // The following default to the windows' vm paths, must explicitly set env variables locally
    CORE_FOLDER: `C:\\Server\\automation\\main\\test-step-handler`,
    PYTHON_VENV: getPythonVenv(`C:\\Server\\automation\\main\\test-step-handler`),
};

